class University {}

class Department {}

class ResearchGroup {
  + Name : string
}

class Researcher {
  + Name : string
}

class Project {}

class WorkPackage {
  + Name : string
}

class Assignment {
  + StartDate : date
  + EndDate : date
}

Department "1" -- "*" ResearchGroup : belongs to
ResearchGroup "1" -- "*" Researcher : belongs to
Project "1" *-- "1..*" WorkPackage : decomposed into
WorkPackage "1" -- "1" ResearchGroup : led by
WorkPackage "1" -- "*" Assignment : has
Researcher "1" -- "*" Assignment : is assigned to

@enduml

